//
// The port, checked against the thing it was ported from.
//
// Fixtures/progression.json was generated by running the web app's own
// lib/engine.ts over 210 combinations of lift, level and history, and keeping
// what it answered. If the Swift rules disagree with it on any one of them,
// the port drifted, and this says which case and in which direction.
//
// Regenerate it from the web repo when a rule is deliberately changed, and
// say so in the commit. Until then, the web app is the specification.

import XCTest
@testable import HabitaBullKit

private struct Case: Decodable {
    let lift: String, level: String, shape: String
    let increment: Double, compound: Bool, heavy: Bool, hold: Bool, cardio: Bool
    let history: [[Pair]]
    let weight: Double, reps: Int, sets: Int, note: String

    struct Pair: Decodable { let weight: Double; let reps: Int }
}

final class PortParityTests: XCTestCase {
    func testEveryAnswerMatchesTheWebEngine() throws {
        let url = try XCTUnwrap(Bundle.module.url(forResource: "progression", withExtension: "json"),
                                "the fixture is missing from the test bundle")
        let cases = try JSONDecoder().decode([Case].self, from: Data(contentsOf: url))
        XCTAssertGreaterThan(cases.count, 100, "the fixture looks truncated")

        var drifted: [String] = []
        /// The one sentence the Swift rules deliberately say differently, and
        /// the count of how often it came up.
        ///
        /// The web engine snaps a hand-typed weight onto the bar under the
        /// words "Same weight. Own it this time.", so 97 lb comes back as 97.5
        /// with a line saying nothing changed. A codex audit 2026-11-17 called
        /// that what it is: the app describing something it did not do. The
        /// app now says "Same weight, rounded to 97.5 lb." The number is the
        /// same on both sides; only the sentence differs,
        /// and only on this one shape.
        ///
        /// Anything else about these cases still has to match, and when the
        /// fixture is regenerated from a web app that says the same thing,
        /// this stops counting and the test says to delete it. Whether the web
        /// app follows is Lucy's call.
        var saidBetter = 0
        /// The second deliberate difference, and the count of the cases it
        /// covers.
        ///
        /// The web engine holds the level's count on a lift it cannot load --
        /// 8 reps, 30 seconds, 20 minutes -- however many she logged, and on a
        /// cleared session says "Add two reps this time" over a number that
        /// never moves. Lucy's call, 2026-11-20: the count stays at whatever
        /// she last logged and changes when she logs a different one. Every
        /// one of these cases is checked against that rule below rather than
        /// waved past; the weight and the set count still have to match the
        /// web engine exactly.
        var heldWhereSheLeftIt = 0
        for c in cases {
            let lift = LiftShape(increment: c.increment, compound: c.compound,
                                 heavy: c.heavy, hold: c.hold, cardio: c.cardio)
            let history = c.history.map { $0.map { DoneSet(weight: $0.weight, reps: $0.reps) } }
            let got = Progression.next(lift, history: history, level: Level(rawValue: c.level)!)
            let where_ = "\(c.lift) · \(c.level) · \(c.shape)"
            if abs(got.weight - c.weight) > 0.0001 { drifted.append("\(where_): weight \(got.weight) vs \(c.weight)") }
            if got.sets != c.sets { drifted.append("\(where_): sets \(got.sets) vs \(c.sets)") }

            // a lift with nothing to load, and a session of hers to carry
            if c.increment == 0, let last = history.first {
                let count = last.map(\.reps).max()
                if got.reps != count {
                    drifted.append("\(where_): count \(got.reps), she logged \(count ?? 0)")
                }
                let expected = c.cardio
                    ? "Same as last time. Change the time or the incline if you want to."
                    : c.hold ? "Same as last time. Change the time if you want to."
                             : "Same as last time. Change the reps if you want to."
                if got.note != expected { drifted.append("\(where_): note \"\(got.note)\"") }
                if got.reps != c.reps || got.note != c.note { heldWhereSheLeftIt += 1 }
                continue
            }

            if got.reps != c.reps { drifted.append("\(where_): reps \(got.reps) vs \(c.reps)") }
            if got.note != c.note {
                // spelled out from this case's own number rather than
                // matched on a prefix and a suffix: those accepted anything
                // in between, the wrong weight included, as a codex audit
                // 2026-11-17 pointed out.
                let said = got.weight == got.weight.rounded()
                    ? String(Int(got.weight)) : String(got.weight)
                let snapped = c.note == "Same weight. Own it this time."
                    && got.note == "Same weight, rounded to \(said) lb."

                if snapped { saidBetter += 1 }
                else { drifted.append("\(where_): note \"\(got.note)\" vs \"\(c.note)\"") }
            }
        }
        XCTAssertEqual(drifted, [], "the Swift rules answer differently from the web engine")
        XCTAssertGreaterThan(heldWhereSheLeftIt, 60,
                             "the unloadable lifts stopped diverging from the web engine. If the "
                             + "fixture was regenerated, check the rule above is still the one "
                             + "Lucy asked for rather than deleting the exception")
        XCTAssertGreaterThan(saidBetter, 0,
                             "nothing hit the one allowed difference any more. If the fixture was "
                             + "regenerated, delete the exception above rather than leaving it to "
                             + "cover a drift nobody meant")
    }
}
